package ph.printshop.pos;

import android.database.sqlite.SQLiteDatabase;
import android.database.Cursor;
import android.content.ContentValues;

/** Isolated durable credit checkout schema, after ReceivableJournal and CreditCashJournal candidates.
 * Training-only CatalogStore API; no cashier UI exposure pending platform acceptance.
 */
final class CreditCheckoutJournal {
    private CreditCheckoutJournal(){}
    static void createCandidate(SQLiteDatabase db){
        db.execSQL("CREATE TABLE credit_checkout_requests (id TEXT PRIMARY KEY NOT NULL, customer_id TEXT NOT NULL, customer_revision INTEGER NOT NULL CHECK(typeof(customer_revision)='integer' AND customer_revision>=1), shift_id TEXT NOT NULL REFERENCES cashier_shifts(id), operator_id TEXT NOT NULL REFERENCES cashier_accounts(id), actor_revision INTEGER NOT NULL CHECK(typeof(actor_revision)='integer' AND actor_revision>=1), fingerprint TEXT NOT NULL CHECK(length(fingerprint)=64 AND fingerprint NOT GLOB '*[^0-9a-f]*'), service_id TEXT NOT NULL REFERENCES catalog(id), service_revision INTEGER NOT NULL CHECK(typeof(service_revision)='integer' AND service_revision>=1), pricing_revision INTEGER NOT NULL CHECK(typeof(pricing_revision)='integer' AND pricing_revision>=0), recipe_revision INTEGER NOT NULL CHECK(typeof(recipe_revision)='integer' AND recipe_revision>=0), billable_hundredths INTEGER NOT NULL CHECK(typeof(billable_hundredths)='integer' AND billable_hundredths BETWEEN 1 AND 10000000), usage_hundredths INTEGER NOT NULL CHECK(typeof(usage_hundredths)='integer' AND usage_hundredths BETWEEN 1 AND 10000000), rate INTEGER NOT NULL CHECK(typeof(rate)='integer' AND rate BETWEEN 1 AND 99999999999), total INTEGER NOT NULL CHECK(typeof(total)='integer' AND total BETWEEN 1 AND 9999999999900000 AND total=(rate*billable_hundredths+50)/100), paid INTEGER NOT NULL CHECK(typeof(paid)='integer' AND paid>=0 AND paid<total), material_count INTEGER NOT NULL CHECK(typeof(material_count)='integer' AND material_count BETWEEN 0 AND 100), created_ms INTEGER NOT NULL CHECK(typeof(created_ms)='integer' AND created_ms>=0), state TEXT NOT NULL CHECK(state IN ('PENDING','APPLIED','CANCELLED')), resolved_ms INTEGER, resolved_revision INTEGER, cancel_reason TEXT, FOREIGN KEY(customer_id,customer_revision) REFERENCES cashier_customer_versions(id,revision), CHECK((state='PENDING' AND resolved_ms IS NULL AND resolved_revision IS NULL AND cancel_reason IS NULL) OR (state IN ('APPLIED','CANCELLED') AND typeof(resolved_ms)='integer' AND resolved_ms>=created_ms AND typeof(resolved_revision)='integer' AND resolved_revision>=actor_revision AND ((state='APPLIED' AND cancel_reason IS NULL) OR (state='CANCELLED' AND cancel_reason IS NOT NULL AND length(trim(cancel_reason)) BETWEEN 1 AND 160)))))");
        db.execSQL("CREATE TABLE credit_checkout_inputs (request_id TEXT PRIMARY KEY NOT NULL REFERENCES credit_checkout_requests(id), input_count INTEGER NOT NULL CHECK(typeof(input_count)='integer' AND input_count BETWEEN 1 AND 100000), pages INTEGER NOT NULL CHECK(typeof(pages)='integer' AND pages BETWEEN 1 AND 100000), copies INTEGER NOT NULL CHECK(typeof(copies)='integer' AND copies BETWEEN 1 AND 100000), width TEXT, height TEXT, dimension_unit TEXT CHECK(dimension_unit IN ('FT','IN','CM','M')), basis TEXT NOT NULL CHECK(basis IN ('NONE','BILLABLE_UNIT','PRODUCED_ITEM')))");
        db.execSQL("CREATE TRIGGER credit_inputs_initial BEFORE INSERT ON credit_checkout_inputs WHEN EXISTS(SELECT 1 FROM credit_checkout_inputs WHERE request_id=NEW.request_id) OR NOT EXISTS(SELECT 1 FROM credit_checkout_requests r WHERE r.id=NEW.request_id AND r.state='PENDING') BEGIN SELECT RAISE(ABORT,'Invalid credit checkout inputs'); END");
        db.execSQL("CREATE TRIGGER credit_inputs_no_update BEFORE UPDATE ON credit_checkout_inputs BEGIN SELECT RAISE(ABORT,'Credit checkout inputs immutable'); END");
        db.execSQL("CREATE TRIGGER credit_inputs_no_delete BEFORE DELETE ON credit_checkout_inputs BEGIN SELECT RAISE(ABORT,'Credit checkout inputs immutable'); END");
        db.execSQL("CREATE UNIQUE INDEX credit_checkout_pending_shift ON credit_checkout_requests(shift_id) WHERE state='PENDING'");
        db.execSQL("CREATE UNIQUE INDEX credit_checkout_pending_customer ON credit_checkout_requests(customer_id) WHERE state='PENDING'");
        db.execSQL("CREATE TABLE credit_checkout_materials (request_id TEXT NOT NULL REFERENCES credit_checkout_requests(id), material_id TEXT NOT NULL REFERENCES catalog(id), movement_id TEXT UNIQUE NOT NULL, unit TEXT NOT NULL, catalog_revision INTEGER NOT NULL CHECK(typeof(catalog_revision)='integer' AND catalog_revision>=1), stock_revision INTEGER NOT NULL CHECK(typeof(stock_revision)='integer' AND stock_revision>=1 AND stock_revision<9223372036854775807), per_unit_milli INTEGER NOT NULL CHECK(typeof(per_unit_milli)='integer' AND per_unit_milli BETWEEN 1 AND 999999999999), quantity_milli INTEGER NOT NULL CHECK(typeof(quantity_milli)='integer' AND quantity_milli BETWEEN 1 AND 999999999999), before_milli INTEGER NOT NULL CHECK(typeof(before_milli)='integer' AND before_milli BETWEEN quantity_milli AND 999999999999), after_milli INTEGER NOT NULL CHECK(typeof(after_milli)='integer' AND after_milli=before_milli-quantity_milli), PRIMARY KEY(request_id,material_id))");
        db.execSQL("CREATE VIEW credit_checkout_current_stock AS SELECT c.id,c.unit,c.revision AS catalog_revision,COALESCE((SELECT m.stock_revision FROM stock_movements m WHERE m.material_id=c.id ORDER BY m.stock_revision DESC LIMIT 1),0) AS stock_revision,COALESCE((SELECT m.after_quantity FROM stock_movements m WHERE m.material_id=c.id ORDER BY m.stock_revision DESC LIMIT 1),0) AS quantity FROM catalog c WHERE c.kind='MATERIAL' AND c.archived=0");
        db.execSQL("CREATE VIEW credit_checkout_valid_service AS SELECT r.id FROM credit_checkout_requests r JOIN catalog c ON c.id=r.service_id AND c.kind='SERVICE' AND c.archived=0 AND c.revision=r.service_revision WHERE r.pricing_revision=COALESCE((SELECT MAX(p.revision) FROM pricing_profile_versions p WHERE p.service_id=c.id),0) AND r.recipe_revision=COALESCE((SELECT MAX(h.revision) FROM recipe_history h WHERE h.service_id=c.id),0) AND r.material_count=(SELECT COUNT(*) FROM service_materials m WHERE m.service_id=c.id) AND r.rate=COALESCE((SELECT t.rate_centavos FROM pricing_tier_versions t WHERE t.service_id=c.id AND t.profile_revision=r.pricing_revision AND t.threshold_hundredths<=r.billable_hundredths ORDER BY t.threshold_hundredths DESC LIMIT 1),c.centavos)");
        db.execSQL("CREATE TRIGGER credit_checkout_initial BEFORE INSERT ON credit_checkout_requests WHEN NEW.state<>'PENDING' OR EXISTS(SELECT 1 FROM credit_checkout_requests WHERE id=NEW.id OR (state='PENDING' AND (shift_id=NEW.shift_id OR customer_id=NEW.customer_id))) OR EXISTS(SELECT 1 FROM checkout_requests WHERE request_id=NEW.id) OR EXISTS(SELECT 1 FROM credit_receivable_sources WHERE id=NEW.id) OR NOT EXISTS(SELECT 1 FROM cashier_customer_current c WHERE c.id=NEW.customer_id AND c.revision=NEW.customer_revision AND c.active=1) OR NOT EXISTS(SELECT 1 FROM cashier_shifts s JOIN cashier_accounts a ON a.id=s.operator_id JOIN cashier_drawer_current b ON b.shift_id=s.id WHERE s.id=NEW.shift_id AND s.state='OPEN' AND a.id=NEW.operator_id AND a.active=1 AND a.revision=NEW.actor_revision AND NEW.created_ms>=s.opened_ms AND b.expected_cash+NEW.paid<=9999999999900000) OR EXISTS(SELECT 1 FROM credit_collection_requests p WHERE p.state='PENDING' AND (p.shift_id=NEW.shift_id OR p.customer_id=NEW.customer_id)) OR EXISTS(SELECT 1 FROM cashier_drawer_requests p WHERE p.shift_id=NEW.shift_id AND p.state='PENDING') OR EXISTS(SELECT 1 FROM cashier_shift_checkouts l JOIN checkout_requests p ON p.request_id=l.request_id WHERE l.shift_id=NEW.shift_id AND p.state='PENDING') BEGIN SELECT RAISE(ABORT,'Invalid pending credit checkout'); END");
        db.execSQL("CREATE TRIGGER credit_checkout_material_initial BEFORE INSERT ON credit_checkout_materials WHEN EXISTS(SELECT 1 FROM credit_checkout_materials WHERE movement_id=NEW.movement_id OR (request_id=NEW.request_id AND material_id=NEW.material_id)) OR EXISTS(SELECT 1 FROM stock_movements WHERE request_id=NEW.movement_id) OR NOT EXISTS(SELECT 1 FROM credit_checkout_requests r JOIN service_materials m ON m.service_id=r.service_id AND m.material_id=NEW.material_id JOIN credit_checkout_current_stock s ON s.id=m.material_id WHERE r.id=NEW.request_id AND r.state='PENDING' AND m.quantity_milli=NEW.per_unit_milli AND NEW.quantity_milli*100=NEW.per_unit_milli*r.usage_hundredths AND m.unit=NEW.unit AND s.unit=NEW.unit AND s.catalog_revision=NEW.catalog_revision AND s.stock_revision=NEW.stock_revision AND s.quantity=NEW.before_milli AND NOT EXISTS(SELECT 1 FROM stock_requests p WHERE p.material_id=m.material_id AND p.state='PENDING') AND (SELECT COUNT(*) FROM credit_checkout_materials x WHERE x.request_id=r.id)<r.material_count) BEGIN SELECT RAISE(ABORT,'Invalid credit material snapshot'); END");
        db.execSQL("CREATE TRIGGER credit_checkout_material_no_update BEFORE UPDATE ON credit_checkout_materials BEGIN SELECT RAISE(ABORT,'Credit material immutable'); END");
        db.execSQL("CREATE TRIGGER credit_checkout_material_no_delete BEFORE DELETE ON credit_checkout_materials BEGIN SELECT RAISE(ABORT,'Credit material immutable'); END");
        db.execSQL("CREATE TRIGGER credit_checkout_no_delete BEFORE DELETE ON credit_checkout_requests BEGIN SELECT RAISE(ABORT,'Credit request immutable'); END");
        db.execSQL("CREATE TRIGGER credit_checkout_resolution BEFORE UPDATE ON credit_checkout_requests WHEN OLD.state<>'PENDING' OR NEW.state NOT IN ('APPLIED','CANCELLED') OR NEW.id IS NOT OLD.id OR NEW.customer_id IS NOT OLD.customer_id OR NEW.customer_revision IS NOT OLD.customer_revision OR NEW.shift_id IS NOT OLD.shift_id OR NEW.operator_id IS NOT OLD.operator_id OR NEW.actor_revision IS NOT OLD.actor_revision OR NEW.fingerprint IS NOT OLD.fingerprint OR NEW.service_id IS NOT OLD.service_id OR NEW.service_revision IS NOT OLD.service_revision OR NEW.pricing_revision IS NOT OLD.pricing_revision OR NEW.recipe_revision IS NOT OLD.recipe_revision OR NEW.billable_hundredths IS NOT OLD.billable_hundredths OR NEW.usage_hundredths IS NOT OLD.usage_hundredths OR NEW.rate IS NOT OLD.rate OR NEW.total IS NOT OLD.total OR NEW.paid IS NOT OLD.paid OR NEW.material_count IS NOT OLD.material_count OR NEW.created_ms IS NOT OLD.created_ms OR NOT EXISTS(SELECT 1 FROM cashier_shifts s JOIN cashier_accounts a ON a.id=s.operator_id WHERE s.id=OLD.shift_id AND s.state='OPEN' AND a.id=OLD.operator_id AND a.active=1 AND a.revision=NEW.resolved_revision) OR (NEW.state='APPLIED' AND (NOT EXISTS(SELECT 1 FROM credit_checkout_inputs i WHERE i.request_id=OLD.id) OR NOT EXISTS(SELECT 1 FROM credit_checkout_valid_service v WHERE v.id=OLD.id) OR (SELECT COUNT(*) FROM credit_checkout_materials WHERE request_id=OLD.id)<>OLD.material_count OR EXISTS(SELECT 1 FROM credit_checkout_materials m LEFT JOIN credit_checkout_current_stock s ON s.id=m.material_id LEFT JOIN service_materials u ON u.service_id=OLD.service_id AND u.material_id=m.material_id WHERE m.request_id=OLD.id AND (s.id IS NULL OR s.catalog_revision<>m.catalog_revision OR s.stock_revision<>m.stock_revision OR s.quantity<>m.before_milli OR s.unit<>m.unit OR u.material_id IS NULL OR u.quantity_milli<>m.per_unit_milli OR u.unit<>m.unit OR EXISTS(SELECT 1 FROM stock_requests p WHERE p.material_id=m.material_id AND p.state='PENDING'))))) BEGIN SELECT RAISE(ABORT,'Invalid credit checkout resolution'); END");
        // A credit source must now be backed by the exact applied request, never inserted standalone.
        db.execSQL("CREATE TRIGGER credit_source_requires_checkout BEFORE INSERT ON credit_receivable_sources WHEN NOT EXISTS(SELECT 1 FROM credit_checkout_requests r WHERE r.id=NEW.id AND r.state='APPLIED' AND r.customer_id=NEW.customer_id AND r.customer_revision=NEW.customer_revision AND r.shift_id=NEW.shift_id AND r.operator_id=NEW.operator_id AND r.resolved_revision=NEW.actor_revision AND r.fingerprint=NEW.plan_fingerprint AND r.total=NEW.total AND r.paid=NEW.paid AND r.resolved_ms=NEW.opened_ms) BEGIN SELECT RAISE(ABORT,'Credit source requires applied checkout'); END");
        db.execSQL("CREATE TRIGGER credit_checkout_apply AFTER UPDATE ON credit_checkout_requests WHEN NEW.state='APPLIED' BEGIN INSERT INTO stock_movements(request_id,material_id,catalog_revision,stock_revision,unit,reason,delta,before_quantity,after_quantity,created_ms) SELECT m.movement_id,m.material_id,m.catalog_revision,m.stock_revision+1,m.unit,'Preview credit checkout '||NEW.id,-m.quantity_milli,m.before_milli,m.after_milli,NEW.resolved_ms FROM credit_checkout_materials m WHERE m.request_id=NEW.id; SELECT CASE WHEN changes()<>NEW.material_count THEN RAISE(ABORT,'Credit stock effects incomplete') END; INSERT INTO credit_receivable_sources VALUES(NEW.id,NEW.customer_id,NEW.customer_revision,NEW.shift_id,NEW.operator_id,NEW.resolved_revision,NEW.fingerprint,NEW.total,NEW.paid,NEW.resolved_ms); SELECT CASE WHEN changes()<>1 THEN RAISE(ABORT,'Credit source missing') END; END");
        db.execSQL("CREATE TRIGGER credit_stock_no_update BEFORE UPDATE ON stock_movements WHEN EXISTS(SELECT 1 FROM credit_checkout_materials m JOIN credit_checkout_requests r ON r.id=m.request_id WHERE m.movement_id=OLD.request_id AND r.state='APPLIED') BEGIN SELECT RAISE(ABORT,'Credit stock effect immutable'); END");
        db.execSQL("CREATE TRIGGER credit_stock_no_delete BEFORE DELETE ON stock_movements WHEN EXISTS(SELECT 1 FROM credit_checkout_materials m JOIN credit_checkout_requests r ON r.id=m.request_id WHERE m.movement_id=OLD.request_id AND r.state='APPLIED') BEGIN SELECT RAISE(ABORT,'Credit stock effect immutable'); END");
        db.execSQL("CREATE TRIGGER credit_pending_blocks_drawer BEFORE INSERT ON cashier_drawer_requests WHEN EXISTS(SELECT 1 FROM credit_checkout_requests r WHERE r.shift_id=NEW.shift_id AND r.state='PENDING') BEGIN SELECT RAISE(ABORT,'Resolve pending credit checkout first'); END");
        db.execSQL("CREATE TRIGGER credit_pending_blocks_checkout BEFORE INSERT ON cashier_shift_checkouts WHEN EXISTS(SELECT 1 FROM credit_checkout_requests r WHERE r.id=NEW.request_id OR (r.shift_id=NEW.shift_id AND r.state='PENDING')) BEGIN SELECT RAISE(ABORT,'Resolve pending credit checkout first'); END");
        db.execSQL("CREATE TRIGGER credit_pending_blocks_collection BEFORE INSERT ON credit_collection_requests WHEN EXISTS(SELECT 1 FROM credit_checkout_requests r WHERE r.state='PENDING' AND (r.shift_id=NEW.shift_id OR r.customer_id=NEW.customer_id)) BEGIN SELECT RAISE(ABORT,'Resolve pending credit checkout first'); END");
        db.execSQL("CREATE TRIGGER credit_pending_blocks_close BEFORE UPDATE ON cashier_shifts WHEN NEW.state='CLOSED' AND EXISTS(SELECT 1 FROM credit_checkout_requests r WHERE r.shift_id=OLD.id AND r.state='PENDING') BEGIN SELECT RAISE(ABORT,'Resolve pending credit checkout first'); END");
    }
    static final class Record {
        final String id,customerId,shiftId,operatorId,serviceId,fingerprint,state,cancelReason,customerName,serviceName;
        final java.util.List<String> materialDetails;
        final long customerRevision,serviceRevision,pricingRevision,recipeRevision,paid,total;
        final CheckoutPlan.Inputs inputs;
        Record(Cursor c,java.util.List<String> details){
            id=c.getString(0);customerId=c.getString(1);customerRevision=c.getLong(2);shiftId=c.getString(3);operatorId=c.getString(4);
            fingerprint=c.getString(5);serviceId=c.getString(6);serviceRevision=c.getLong(7);pricingRevision=c.getLong(8);recipeRevision=c.getLong(9);
            total=c.getLong(10);paid=c.getLong(11);state=c.getString(12);cancelReason=c.getString(13);String unit=c.getString(19);
            customerName=c.getString(21);serviceName=c.getString(22);materialDetails=java.util.Collections.unmodifiableList(new java.util.ArrayList<>(details));
            inputs=new CheckoutPlan.Inputs(c.getInt(14),c.getInt(15),c.getInt(16),c.getString(17),c.getString(18),unit==null?null:PricingMath.DimensionUnit.valueOf(unit),CheckoutPlan.UsageBasis.valueOf(c.getString(20)),paid);
        }
        void requireIdentity(String fingerprint){if(!this.fingerprint.equals(fingerprint))throw new IllegalStateException("Credit checkout identity changed");}
    }
    static Record read(SQLiteDatabase db,String id){
        java.util.List<String> details=new java.util.ArrayList<>();
        try(Cursor c=db.rawQuery("SELECT COALESCE(h.name,m.material_id),m.quantity_milli,m.unit FROM credit_checkout_materials m LEFT JOIN catalog_history h ON h.id=m.material_id AND h.revision=m.catalog_revision WHERE m.request_id=? ORDER BY m.material_id",new String[]{id})){
            while(c.moveToNext())details.add(StockMath.display(c.getLong(1))+" "+c.getString(2)+" ("+c.getString(0)+")");
        }
        try(Cursor c=db.rawQuery("SELECT r.id,r.customer_id,r.customer_revision,r.shift_id,r.operator_id,r.fingerprint,r.service_id,r.service_revision,r.pricing_revision,r.recipe_revision,r.total,r.paid,r.state,r.cancel_reason,i.input_count,i.pages,i.copies,i.width,i.height,i.dimension_unit,i.basis,v.name,COALESCE(h.name,r.service_id) FROM credit_checkout_requests r JOIN credit_checkout_inputs i ON i.request_id=r.id JOIN cashier_customer_versions v ON v.id=r.customer_id AND v.revision=r.customer_revision LEFT JOIN catalog_history h ON h.id=r.service_id AND h.revision=r.service_revision WHERE r.id=?",new String[]{id})){
            return c.moveToFirst()?new Record(c,details):null;
        }
    }
    static void stage(SQLiteDatabase db,CashierJournal.Principal actor,String shift,CreditCheckoutPlan plan,long now){
        ContentValues r=new ContentValues();r.put("id",plan.id);r.put("customer_id",plan.customerId);r.put("customer_revision",plan.customerRevision);
        r.put("shift_id",shift);r.put("operator_id",actor.id);r.put("actor_revision",actor.revision);r.put("fingerprint",plan.fingerprint);
        r.put("service_id",plan.serviceId);r.put("service_revision",plan.serviceRevision);r.put("pricing_revision",plan.pricingRevision);r.put("recipe_revision",plan.recipeRevision);
        r.put("billable_hundredths",plan.billableHundredths);r.put("usage_hundredths",plan.usageHundredths);r.put("rate",plan.rate);r.put("total",plan.total);r.put("paid",plan.paid);
        r.put("material_count",plan.materials.size());r.put("created_ms",now);r.put("state","PENDING");db.insertOrThrow("credit_checkout_requests",null,r);
        CheckoutPlan.Inputs input=plan.actualInputs;ContentValues i=new ContentValues();i.put("request_id",plan.id);i.put("input_count",input.count);i.put("pages",input.pages);i.put("copies",input.copies);
        i.put("width",input.width);i.put("height",input.height);i.put("dimension_unit",input.dimensionUnit==null?null:input.dimensionUnit.name());i.put("basis",input.basis.name());db.insertOrThrow("credit_checkout_inputs",null,i);
        for(CheckoutPlan.Consumption m:plan.materials){
            ContentValues v=new ContentValues();v.put("request_id",plan.id);v.put("material_id",m.materialId);v.put("movement_id",java.util.UUID.randomUUID().toString());
            v.put("unit",m.unit);v.put("catalog_revision",m.catalogRevision);v.put("stock_revision",m.stockRevision);v.put("per_unit_milli",m.perUnitMilli);
            v.put("quantity_milli",m.quantityMilli);v.put("before_milli",m.beforeMilli);v.put("after_milli",m.afterMilli);db.insertOrThrow("credit_checkout_materials",null,v);
        }
    }
    static Record resolve(SQLiteDatabase db,CashierJournal.Principal actor,String id,boolean apply,String reason,long now){
        ContentValues r=new ContentValues();r.put("state",apply?"APPLIED":"CANCELLED");r.put("resolved_ms",now);r.put("resolved_revision",actor.revision);
        if(reason==null)r.putNull("cancel_reason");else r.put("cancel_reason",reason);
        if(db.update("credit_checkout_requests",r,"id=? AND state='PENDING'",new String[]{id})!=1)throw new IllegalStateException("Credit resolution unavailable");
        return read(db,id);
    }
}
